// Reserved transport arguments are accepted on every endpoint tool. They are
// not request fields, so an unused one is ignored instead of copied onto the
// wire. Declared bindings with these names still flow through knownArgs.
func mcpReservedArg(name string) bool {
	switch name {
	case "cursor", "body_json", "body_base64", "content_type":
		return true
	default:
		return false
	}
}

func rejectUndeclaredMCPArgs(args map[string]any, knownArgs, pathParams map[string]bool) error {
	var unknown []string
	for name := range args {
		if pathParams[name] || knownArgs[name] || mcpReservedArg(name) {
			continue
		}
		unknown = append(unknown, name)
	}
	if len(unknown) == 0 {
		return nil
	}
	sort.Strings(unknown)
	candidates := mcpArgCandidates(knownArgs, pathParams)
	parts := make([]string, len(unknown))
	for i, name := range unknown {
		parts[i] = formatUnknownMCPArg(name, suggestMCPArg(name, candidates))
	}
	return fmt.Errorf("%s", strings.Join(parts, "; "))
}

func mcpArgCandidates(knownArgs, pathParams map[string]bool) []string {
	names := make([]string, 0, len(knownArgs)+len(pathParams))
	seen := make(map[string]struct{}, len(knownArgs)+len(pathParams))
	for name := range knownArgs {
		if _, ok := seen[name]; ok {
			continue
		}
		seen[name] = struct{}{}
		names = append(names, name)
	}
	for name := range pathParams {
		if _, ok := seen[name]; ok {
			continue
		}
		seen[name] = struct{}{}
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func formatUnknownMCPArg(name, suggestion string) string {
	if suggestion == "" {
		return fmt.Sprintf("unknown argument %q", name)
	}
	return fmt.Sprintf("unknown argument %q (did you mean %q?)", name, suggestion)
}

func suggestMCPArg(name string, candidates []string) string {
	folded := mcpArgFold(name)
	stripped := mcpArgStrip(folded)
	best := ""
	bestDist := 0
	ambiguous := false
	consider := func(cand string, dist int) {
		if best == "" || dist < bestDist {
			best = cand
			bestDist = dist
			ambiguous = false
			return
		}
		if dist == bestDist && cand != best {
			ambiguous = true
		}
	}
	for _, cand := range candidates {
		if cand == "" || cand == name {
			continue
		}
		cf := mcpArgFold(cand)
		if cf == folded {
			consider(cand, 0)
			continue
		}
		if stripped != "" && mcpArgStrip(cf) == stripped {
			consider(cand, 0)
			continue
		}
		dist := runeLevenshtein(folded, cf)
		if mcpArgDistanceOK(folded, cf, dist) {
			consider(cand, dist)
		}
	}
	if ambiguous {
		return ""
	}
	return best
}

func mcpArgFold(name string) string {
	return strings.ReplaceAll(strings.ToLower(name), "-", "_")
}

func mcpArgStrip(folded string) string {
	return strings.ReplaceAll(folded, "_", "")
}

func mcpArgDistanceOK(a, b string, dist int) bool {
	if dist <= 0 {
		return false
	}
	la, lb := len([]rune(a)), len([]rune(b))
	if la < 3 || lb < 3 {
		return false
	}
	if la >= 5 && lb >= 5 {
		return dist <= 2
	}
	return dist <= 1
}

func runeLevenshtein(a, b string) int {
	ar, br := []rune(a), []rune(b)
	if len(ar) == 0 {
		return len(br)
	}
	if len(br) == 0 {
		return len(ar)
	}
	prev := make([]int, len(br)+1)
	cur := make([]int, len(br)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ar); i++ {
		cur[0] = i
		for j := 1; j <= len(br); j++ {
			cost := 1
			if ar[i-1] == br[j-1] {
				cost = 0
			}
			del, ins, sub := prev[j]+1, cur[j-1]+1, prev[j-1]+cost
			cur[j] = del
			if ins < cur[j] {
				cur[j] = ins
			}
			if sub < cur[j] {
				cur[j] = sub
			}
		}
		prev, cur = cur, prev
	}
	return prev[len(br)]
}

func mcpToolPageResultText(method string, data json.RawMessage, pageConfig mcpPageConfig, cursor string) *mcplib.CallToolResult {
	return mcpToolPageResultTextWithPlatform(method, data, pageConfig, cursor, "", false, nil)
}

func mcpToolPageResultTextWithPlatform(method string, data json.RawMessage, pageConfig mcpPageConfig, cursor, requestCursor string, readOnly bool, platformSession *platform.Session) *mcplib.CallToolResult {
	result := bound.EndpointPageResponse(method, data, bound.PageOptions{
		Cursor:               cursor,
		CursorParam:          pageConfig.CursorParam,
		NextCursorPath:       pageConfig.NextCursorPath,
		HasMoreField:         pageConfig.HasMoreField,
		RequestCursor:        requestCursor,
		ReadOnly:             readOnly,
		ExternalContinuation: pageConfig.ExternalContinuation,
	})
	if platformSession != nil {
		result = bound.WithMetadata(result, platformSession.OutputMetadata())
	}
	return mcplib.NewToolResultText(result)
}

func newMCPClient(ctx context.Context) (*client.Client, *platform.Session, error) {
	cfg, err := newMCPConfig()
	if err != nil {
		return nil, nil, err
	}
	return newMCPClientFromConfig(ctx, cfg)
}

func newMCPConfig() (*config.Config, error) {
	cfg, err := config.Load("")
	if err != nil {
		return nil, fmt.Errorf("loading config: %w", err)
	}
	return cfg, nil
}

func newMCPClientFromConfig(ctx context.Context, cfg *config.Config) (*client.Client, *platform.Session, error) {
	c := client.New(cfg, 60*time.Second, defaultMCPRateLimit)
	if tlsErr := c.TLSConfigError(); tlsErr != nil {
		return nil, nil, tlsErr
	}
	// Agents calling through MCP need fresh data every call. The on-disk
	// response cache survives across MCP server invocations, so a
	// DELETE/PATCH followed by a GET would otherwise return the
	// pre-mutation snapshot for up to the cache TTL. The interactive CLI
	// constructs its own client and is unaffected.
	c.NoCache = true
	session, err := cli.BindMCPClient(ctx, c)
	if err != nil {
		return nil, nil, err
	}
	if err := cli.ApplyClientHooks(c); err != nil {
		if session != nil {
			session.ZeroCredentials()
		}
		return nil, nil, fmt.Errorf("initializing MCP client: %w", err)
	}
	return c, session, nil
}

func mcpDBPath() (string, error) {
	return cli.MCPStorePath()
}

// toolResultJSON renders v as the indented JSON body of an MCP text result,
// surfacing a marshal failure as a tool error instead of empty content.
func toolResultJSON(v any) (*mcplib.CallToolResult, error) {
	text, err := bound.JSON(v)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result: %v", err)), nil
	}
	return mcplib.NewToolResultText(text), nil
}
func registeredCommandMirrorCapabilities(s *server.MCPServer, capabilities []map[string]string) []map[string]string {
	registered := make([]map[string]string, 0, len(capabilities))
	root := cli.RootCmd()
	for _, capability := range capabilities {
		toolName := cobratree.ToolNameForCommand(s, root, capability["cli_command"])
		if toolName == "" {
			continue
		}
		entry := s.GetTool(toolName)
		if entry == nil || entry.Tool.Meta == nil || entry.Tool.Meta.AdditionalFields["pp:tenant-gate"] != "child-cli" {
			continue
		}
		capability["mcp_tool"] = toolName
		registered = append(registered, capability)
	}
	return registered
}

func handleContext(s *server.MCPServer) func(context.Context, mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	return func(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
		return handleContextResult(s, ctx, req)
	}
}

func handleContextResult(s *server.MCPServer, _ context.Context, _ mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	paths := map[string]string{}
	if dir, err := cliutil.ConfigDir(); err == nil {
		paths["config_dir"] = dir
	}
	if dir, err := cliutil.DataDir(); err == nil {
		paths["data_dir"] = dir
	}
	if dir, err := cliutil.StateDir(); err == nil {
		paths["state_dir"] = dir
	}
	if dir, err := cliutil.CacheDir(); err == nil {
		paths["cache_dir"] = dir
	}
	ctx := map[string]any{
		"api":         "pingenerator",
		"description": "Every Pin Generator MCP tool as a typed command, with credit-safe dry runs, preflight pricing and a local spend ledger.",
		"archetype":   "generic",
		"tool_count":  len(s.ListTools()),
		"paths":       paths,
		// tool_surface tells agents which surface a capability lives on.
		"tool_surface": "MCP exposes typed endpoint tools plus a runtime mirror of user-facing CLI commands. Endpoint tools keep typed schemas; command-mirror tools shell out to the companion pingenerator-pp-cli binary.",
		// learn_protocol is generated from the single shared source of
		// truth (the exported constant internal/learn.RecallFirstProtocol)
		// also consumed by the CLI agent-context command, so the MCP and
		// CLI agent surfaces cannot drift.
		"learn_protocol": learn.RecallFirstProtocol,
		"auth": map[string]any{
			"type": "bearer_token",
			"env_vars": []map[string]any{
				{
					"name":        "PINGENERATOR_ACCESS_KEY",
					"kind":        "per_call",
					"required":    true,
					"sensitive":   true,
					"description": "Set to your API credential.",
				},
			},
		},
		"resources": []map[string]any{
			{
				"name":        "mcp",
				"description": "Raw Pin Generator MCP JSON-RPC access (escape hatch for tools not yet typed)",
				"endpoints":   []string{"rpc"},
				"searchable":  true,
				"writable":    true,
			},
		},
		"query_tips": []string{
			"Pagination uses cursor-based paging. Pass after parameter for subsequent pages.",
			"Control page size with the limit parameter (default 100).",
		},
		// Command-mirror capabilities are exposed through MCP by shelling out
		// to the companion CLI binary.
		"command_mirror_capabilities": registeredCommandMirrorCapabilities(s, []map[string]string{
			{"name": "Post to pin", "command": "pin-post", "cli_command": "pin-post", "description": "Turn a blog post URL into a scheduled Pinterest pin in one command, previewed for free before any credit is spent.", "rationale": "Chains post extraction into pin generation with a credit guard and a local spend ledger that the vendor's MCP tools do", "via": "mcp-command-mirror"},
			{"name": "Plan preflight", "command": "preflight", "cli_command": "preflight", "description": "Price a planned batch in credits and confirm the profile, board and design profile exist before spending anything.", "rationale": "Combines a credit cost table with live account, profile, board and design-profile reads", "via": "mcp-command-mirror"},
			{"name": "Products to pins", "command": "pin-products", "cli_command": "pin-products", "description": "Turn a connected store's products into a batch of scheduled pins", "rationale": "Pages through store products and plans one pin per product against a local ledger", "via": "mcp-command-mirror"},
			{"name": "Unpinned posts", "command": "unpinned-posts", "cli_command": "unpinned-posts", "description": "List sitemap posts that have no scheduled pin and no ledgered spend.", "rationale": "Joins sitemap posts with the scheduled-pin queue and the local ledger; no single tool can answer it.", "via": "mcp-command-mirror"},
			{"name": "Spend ledger", "command": "ledger", "cli_command": "ledger", "description": "See every credit-spending call this CLI executed, including unconfirmed ones that may have spent", "rationale": "The MCP surface exposes no spend history; the ledger is local state written by --execute paths.", "via": "mcp-command-mirror"},
			{"name": "Queue gaps", "command": "queue-gaps", "cli_command": "queue-gaps", "description": "Find empty and overloaded days in the scheduled-pin queue, per board.", "rationale": "Aggregates the scheduled-pin list by day and board, which the raw list does not show.", "via": "mcp-command-mirror"},
			{"name": "Credit runway", "command": "credit-runway", "cli_command": "credit-runway", "description": "Estimate weekly credit burn from active automations and how many days of credit remain.", "rationale": "Joins automation cadence with the account balance; Pin Generator shows neither forecast.", "via": "mcp-command-mirror"},
		}),
		"playbook": []map[string]string{
			{"topic": "Post to pin", "insight": "Chains post extraction into pin generation with a credit guard and a local spend ledger that the vendor's MCP tools do not provide."},
			{"topic": "Plan preflight", "insight": "Combines a credit cost table with live account, profile, board and design-profile reads; no single tool answers whether a plan will succeed."},
			{"topic": "Products to pins", "insight": "Pages through store products and plans one pin per product against a local ledger, which the vendor tools leave to manual repetition."},
			{"topic": "Unpinned posts", "insight": "Joins sitemap posts with the scheduled-pin queue and the local ledger; no single tool can answer it."},
			{"topic": "Spend ledger", "insight": "The MCP surface exposes no spend history; the ledger is local state written by --execute paths."},
			{"topic": "Queue gaps", "insight": "Aggregates the scheduled-pin list by day and board, which the raw list does not show."},
			{"topic": "Credit runway", "insight": "Joins automation cadence with the account balance; Pin Generator shows neither forecast."},
		},
	}
	return toolResultJSON(ctx)
}

// RegisterNovelFeatureTools is kept as a compatibility no-op for older MCP
// mains. New generated mains call RegisterTools only; RegisterTools now
// includes the runtime Cobra-tree mirror.
func RegisterNovelFeatureTools(s *server.MCPServer) {
	_ = s
}
